      "description": "Recycling Coordinator manages sorting processes at the Sorting Facility."
    },
    {
      "from": "Recycling Coordinator",
      "to": "Contamination Issue",
      "description": "Recycling Coordinator identifies and reports Contamination Issues in waste loads."
    },
    {
      "from": "Contamination Issue",
      "to": "Collection Manager",
      "description": "Contamination Issue is reported to Collection Manager for review and action."
    },
    {
      "from": "Recycling Coordinator",
      "to": "Material Transfer",
      "description": "Recycling Coordinator oversees Material Transfer of sorted materials."
    },
    {
      "from": "Material Transfer",
